-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): petrophysics.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/petrophysics.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE
--   pickett_a_rw and pickett_m graded the water-leg fit (2075 to 2078 m), which
--   returns exactly the given Rw 0.05 and m 2 pre-filled in the parameter card,
--   so both were answerable with no fit (guess_p 1.0). The fields are replaced
--   by the same fit over 2072 to 2078 m, a window the panel invites the learner
--   to try (12 points, 3 m above the water leg), read in PickettExplorer after
--   setting the window and clicking Fit water line. m is tightened to 0.0002 and
--   the panel now prints fitted m to 4 dp, because at 0.002 the course's printed
--   NTG 0.878 (18.0/20.5) and a shaly-sand 0.8769 would pass as m.
--   RE-KEY pickett_a_rw (expected 0.05, tol 0.002)
--       -> pickett_a_rw_2072_2078 'Pickett fit over 2072 to 2078 m: a·Rw' Ω·m, expected 0.6886854786769905, tol 0.002
--   RE-KEY pickett_m (expected 2.0, tol 0.02)
--       -> pickett_m_2072_2078 'Pickett fit over 2072 to 2078 m: cementation exponent m' -, expected 0.8784525453945112, tol 0.0002
--   TIGHTEN phind_avg_sand_a (expected 0.17615030026601647) tol 0.005 -> 0.002:
--       the Root mean square combine one click away prints 0.1805, 0.0043 off, and
--       passed at 0.005
--   TIGHTEN phiw_avg_sand_a (expected 0.2069057569286416) tol 0.005 -> 0.002:
--       the density porosity mean printed beside it, 0.2022, is 0.0047 off and
--       passed at 0.005
--   PROMPT was: fit a Pickett line in the water leg (2075–2078 m)
--   PROMPT now: fit a Pickett line over 2072 to 2078 m, a window that starts
--   three metres above the water leg
--   PROMPT was: Report the SAND_A (2010–2030 m) zone means and the Pickett fit.
--   PROMPT now: Report the SAND_A (2010 to 2030 m) zone means and the Pickett
--   fit over 2072 to 2078 m.
--
-- ADVANCED
--   TIGHTEN rw_arps (expected 0.049910478128179045) tol 0.0005 -> 5e-05:
--       the given Rw 0.05 and the Pickett fit 0.0500 sit 0.00009 off and passed with
--       no Arps work; the printed 0.0499 still passes
--   TIGHTEN rwe_ssp (expected 0.049831180824251246) tol 0.0005 -> 5e-05:
--       the known Rw 0.0500 sits 0.00017 off and passed; the printed 0.0498 still
--       passes
--   TIGHTEN sw_waterleg_mean (expected 0.9991043802143901) tol 0.005 -> 0.0005:
--       the textbook "about 1" passed at 0.005 (0.0009 off); the printed 0.9991
--       still passes
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves:
-- petrophysics/intermediate, petrophysics/advanced. Before it writes, the file
-- counts academy_capstone_attempts on each and REFUSES if any exist, unless D5
-- allowlists that tier with the exact attempt ids (allowlist: empty). Stored
-- scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- petrophysics / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 petrophysics refused: petrophysics/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fe0bae21c778e591c0f5ef2142f49c63' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.005, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.005, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit: a·Rw", "expected": 0.05}, {"key": "pickett_m", "tol": 0.02, "unit": "-", "label": "Pickett fit: cementation exponent m", "expected": 2.0}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb then 'old'
              when md5(prompt) = '23f7efbf38f104a86d05616a8f4a1355' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb then 'new'
              when md5(prompt) = '4fc93836432a158c77906d14bf752067' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w1 petrophysics refused: petrophysics/intermediate matches neither its published form (prompt md5 fe0bae21c778e591c0f5ef2142f49c63) nor its W1 form (prompt md5 23f7efbf38f104a86d05616a8f4a1355), with the fields this file was generated against';
  end if;

  -- petrophysics / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'petrophysics' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 petrophysics refused: petrophysics/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fc73fb0f8363d2b7cec10185793978da' and fields = '[{"key": "rw_arps", "tol": 0.0005, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 0.0005, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb then 'old'
              when md5(prompt) = 'fc73fb0f8363d2b7cec10185793978da' and fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb then 'new'
              when md5(prompt) = '83efe3c343b9a73cbb8c6d9519c4ced2' and fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'petrophysics' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w1 petrophysics refused: petrophysics/advanced matches neither its published form (prompt md5 fc73fb0f8363d2b7cec10185793978da) nor its W1 form (prompt md5 fc73fb0f8363d2b7cec10185793978da), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w1 petrophysics: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 petrophysics refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'petrophysics' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'petrophysics/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'petrophysics/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 petrophysics refused: petrophysics/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 petrophysics: petrophysics/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 petrophysics refused: petrophysics/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'petrophysics' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'petrophysics/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'petrophysics/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 petrophysics refused: petrophysics/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 petrophysics: petrophysics/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 petrophysics refused: petrophysics/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Using the typewell parameters as given: compute neutron-density (average) and Wyllie sonic porosity, fit a Pickett line over 2072 to 2078 m, a window that starts three metres above the water leg, and evaluate Simandoux and Indonesia water saturation with linear Vsh. Report the SAND_A (2010 to 2030 m) zone means and the Pickett fit over 2072 to 2078 m.',
           fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb
     where app_slug = 'petrophysics' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 petrophysics refused: petrophysics/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '23f7efbf38f104a86d05616a8f4a1355' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb)
        or (md5(prompt) = '4fc93836432a158c77906d14bf752067' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb) from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 petrophysics refused: petrophysics/intermediate does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'A lab measured the formation water sample at 0.114 ohm.m at 75 degF; formation temperature is 180 degF. The SP quicklook reads SSP = -93 mV with Rmfe = 0.62 ohm.m at formation temperature. Correct the sample with Arps, convert the SSP, and confirm both against the Pickett fit from the Professional tier. Then book SAND_A twice: with the corrected Rw and with the raw sample value, and watch what the wrong Rw does to pay.',
           fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb
     where app_slug = 'petrophysics' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 petrophysics refused: petrophysics/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
